# NOTE: BayesFactor, hypergeo, and openintro are not available as precompiled
# WebAssembly binaries for Shinylive/webR, so this app no longer depends on
# them. functions.R now includes base-R replacements (hyp2f1, ttestBF10log)
# for the BayesFactor/hypergeo calculations; openintro was unused (functions.R
# already defines its own normTail()/FTail() which shadowed it).
source("functions.R")

shinyServer(function(input, output) { 

  # functions for Bayes factor calculator

  observeEvent(input$test, 
               {
                 if(input$test == "ttest"){
                   updateRadioButtons(inputId = "design",
                              label = "Design:",
                              choiceNames = c("Single sample",
                                              "Independent samples"),
                              choiceValues = c("single",
                                               "independent"),
                              selected = "single"
                 )

                   updateRadioButtons(inputId = "direction",
                                label = "Predicted direction:",
                                choiceNames = c("None",
                                                "Positive effect",
                                                "Negative effect"),
                                choiceValues = c("none", "positive", "negative"),
                                selected = "none"
                   )
                 }
                 else if(input$test == "cor"){
                   updateRadioButtons(inputId = "design",
                                      label = "Type of correlation:",
                                      choiceNames = c("Pearson"),
                                      choiceValues = c("pearson"),
                                      selected = "pearson"
                   )

                   updateRadioButtons(inputId = "direction",
                                      label = "Predicted direction:",
                                      choiceNames = c("None"),
                                      choiceValues = c("none"),
                                      selected = "none"
                   )
                 }
                 else {
                   updateRadioButtons(inputId = "design",
                                      label = "Design:",
                                      choiceNames = c("Between subjects",
                                                      "Repeated measures"),
                                      choiceValues = c("between",
                                                       "repeated"),
                                      selected = "between"
                                      )
                   updateRadioButtons(inputId = "direction",
                                label = "Predicted direction:",
                                choiceNames = c("None"),
                                choiceValues = c("none"),
                                selected = "none"
                   )
                 }
               }
  )


  output$statistic = renderUI(
    if (input$test == "ttest"){
      numericInput(inputId = "t",
                   label = "t-statistic:",
                   value = 0,
                   min = -1e5,
                   max = 1e5,
                   step=0.1
      )
    }
    else if (input$test == "cor"){
      numericInput(inputId = "rObs",
                   label = "Observed correlation:",
                   value = 0,
                   min = -1,
                   max = 1,
                   step=0.01
      )
    }
    else {
      numericInput(inputId = "F",
                   label = "F-statistic:",
                   value = 1,
                   min = 0,
                   max = 1e5,
                   step=0.1
      )
    }
  )

  output$sample1 = renderUI(
    {
      if (input$design == "single"){
        numericInput(inputId = "n",
                     label = "Sample size:",
                     value = 10,
                     min = 2,
                     max = 1e5
        )
      }
      else if (input$design == "independent")
      {
        numericInput(inputId = "n1",
                     label = "Sample size for Group 1:",
                     value = 10,
                     min = 2,
                     max = 1e5
        )
      }
      else if (input$test == "cor")
      {
        numericInput(inputId = "n",
                     label = "Sample size:",
                     value = 10,
                     min = 2,
                     max = 1e5
        )
      }
      else {
        numericInput(inputId = "df1",
                     label = "Numerator df:",
                     value = 1,
                     min = 1,
                     max = 10
                     )
      }
    })

  output$sample2 = renderUI(
    {
      if (input$design == "independent"){
        numericInput(inputId = "n2",
                     label = "Sample size for Group 2:",
                     value = 10,
                     min = 2,
                     max = 1e5
        )
      }
      else if (input$design == "between" | input$design == "repeated"){
        numericInput(inputId = "df2",
                     label = "Denominator df:",
                     value = 1,
                     min = 1,
                     max = 100
        )
      }
    })


  # get input and calculate Bayes factor

  values = reactiveValues()

  observe({

    if (input$direction == "none"){
      A <- -Inf
      B <- Inf
    }
    else if (input$direction == "positive"){
      A <- 0
      B <- Inf
    }
    else if (input$direction == "negative"){
      A <- -Inf
      B <- 0
    }

    if (input$design == "single"){
      if (is.null(input$n)){
        shiny:::flushReact()
        return()
      }
      req(input$n, input$t, input$pH0)
      n1 = max(input$n, 2)
      logBF10 <- ttestBF10log(t = input$t, n1 = n1, nullInterval = c(A,B))
      values$BF10 <- exp(logBF10)
      values$BF01 <- 1/exp(logBF10)
      values$pOdds = input$pH0/(1-input$pH0)
    }
    else if (input$design == "independent"){
      if (is.null(input$n1) | is.null(input$n2)){
        shiny:::flushReact()
        return()
      }
      req(input$t, input$pH0, input$n1, input$n2)
      n1 = max(input$n1, 2)
      n2 = max(input$n2, 2)
      logBF10 <- ttestBF10log(t = input$t, n1 = n1, n2 = n2, nullInterval = c(A,B))
      values$BF10 <- exp(logBF10)
      values$BF01 <- 1/exp(logBF10)
      values$pOdds = input$pH0/(1-input$pH0)
    }
    else if (input$test == "cor"){
      if (is.null(input$n)){
        shiny:::flushReact()
        return()
      }
      req(input$rObs, input$pH0, input$n)
      n = max(input$n, 2)
      kappa=1
      logHyperTerm <- (1/kappa+1-n/2)*log(1-input$rObs^2) +
        log(hyp2f1(a=(1/kappa+1/2), b=(1/kappa+1/2), c=(1/kappa+n/2), z=input$rObs^2))
      logBetaTerms <- lbeta(1/kappa+(n-1)/2, 1/2)-lbeta(1/kappa, 1/2)
      logResult <- logBetaTerms + logHyperTerm

      values$BF10 <- exp(logResult)
      values$BF01 <- 1/exp(logResult)
      values$pOdds = input$pH0/(1-input$pH0)
    }
    else if (input$design == "between"){
      if (is.null(input$df1) | is.null(input$df2)){
        shiny:::flushReact()
        return()
      }
      values$BF01 <- bf_analytic(F=input$F, df1=input$df1, df2=input$df2, repeated=FALSE, report.as="BF01")
      values$BF10 <- bf_analytic(F=input$F, df1=input$df1, df2=input$df2, repeated=FALSE, report.as="BF10")
      values$pOdds = input$pH0/(1-input$pH0)
    }

    else if (input$design == "repeated"){
      if (is.null(input$df1) | is.null(input$df2)){
        shiny:::flushReact()
        return()
      }
      values$BF01 <- bf_analytic(F=input$F, df1=input$df1, df2=input$df2, repeated=TRUE, report.as="BF01")
      values$BF10 <- bf_analytic(F=input$F, df1=input$df1, df2=input$df2, repeated=TRUE, report.as="BF10")
      values$pOdds = input$pH0/(1-input$pH0)
    }

  })




  # render outputs (plot and text)

  # Output 1 - bayes factor "pizza" plot
  output$pizza <- renderPlot({

    op <- par(mar = c(0, 0, 0, 0))

    xPos = 0.2
    yPos = 0.7
    radius = 0.2
    A = pi*radius^2
    alpha = 2/(1/values$BF01+1)*A/radius^2
    startpos = pi/2 - alpha/2
    plotrix::floating.pie(xPos,yPos,c(values$BF01,1),radius=radius,col=c("#4F2D7F","white"),lwd=2,startpos=startpos)
    text(xPos, yPos+1.2*radius, "data|H0", cex=1.5, font=2)
    text(xPos, yPos-1.22*radius, "data|H1", cex=1.5, font=2)
  },
  width=600,
  height=600
  )

  # Output 2 - text describing Bayes factor
  output$bfText <- renderUI({
    if (is.null(values$BF10)){
      shiny:::flushReact()
      return()
    }

    if (values$BF01 > 1){
      p(withMathJax(sprintf("The Bayes factor for the null is \\(\\text{BF}_{01}\\) = %.2f", values$BF01)))
    }

    else if (values$BF10 > 1){
      p(withMathJax(sprintf("The Bayes factor for the alternative is \\(\\text{BF}_{10}\\) = %.2f", values$BF10)))
    }
  })

  output$description <- renderUI({
    if (is.null(values$BF10)){
      shiny:::flushReact()
      return()
    }

    if(values$BF10 > 1){
      p(withMathJax(sprintf("This means that the observed data are approximately %.2f times more likely under \\(H_1\\) than under \\(H_0\\)", values$BF10)))
    }
    else{
      p(withMathJax(sprintf("This means that the observed data are approximately %.2f times more likely under \\(H_0\\) than under \\(H_1\\)", values$BF01)))

    }
  })

  # Output 3 - text describing posterior probabilities
  output$postNull <- renderUI({
    p(withMathJax(sprintf("The posterior probability for \\(H_0\\) is %.4f", (values$BF01*values$pOdds)/(1+(values$BF01*values$pOdds)))))
  })

  output$postAlt <- renderUI({
    p(withMathJax(sprintf("The posterior probability for \\(H_1\\) is %.4f", 1-(values$BF01*values$pOdds)/(1+(values$BF01*values$pOdds)))))
  })


  # Model definition outputs (at top of page)

  output$nullText <- renderUI({

    if (input$test == "ttest"){
      p(withMathJax(sprintf('\\(H_0\\): effect size is equal to 0')))
    }
    else if (input$test == "cor"){
      p(withMathJax(sprintf('\\(H_0\\): correlation is equal to 0')))
    }
    else if (input$test == "anova"){
      p(withMathJax(sprintf('\\(H_0\\): all condition means are equal')))
    }

  })

  output$altText <- renderUI({

    if (input$test == "cor"){
      p(withMathJax(sprintf('\\(H_1\\): correlation is not equal to 0')))
    }
    else if (input$test == "ttest" & input$direction == "positive"){
      p(withMathJax(sprintf('\\(H_1\\): effect size is greater than 0')))
    }
    else if (input$test == "ttest" & input$direction == "negative"){
      p(withMathJax(sprintf('\\(H_1\\): effect size is less than 0')))
    }
    else if (input$test == "ttest" & input$direction == "none"){
      p(withMathJax(sprintf('\\(H_1\\): effect size is not equal to 0')))
    }
    else if (input$test == "anova"){
      p(withMathJax(sprintf('\\(H_1\\): not all condition means are equal')))
    }

  })

# functions for probability calculator

  output$tail = renderUI(
    {
      if (input$dist == "rf"){
        selectInput(inputId = "tail",
                    label = "Find Area:",
                    choices = c("Upper Tail"="upper"),
                    selected = "upper")
      }
      else
      {
        selectInput(inputId = "tail",
                    label = "Find Area:",
                    choices = c("Lower Tail"="lower", 
                                "Upper Tail"="upper", 
                                "Both Tails"="both",
                                "Middle"="middle"),
                    selected = "upper")
      }
    })

  get_region_text = reactive(
    {
      if (is.null(input$tail)){
        shiny:::flushReact()
        return()
      }

      low_less = "<"
      low_greater = ">"

      up_less = "<"
      up_greater = ">"

      text = ""
      if (length(input$tail) != 0)
      {
        if (input$tail == "lower")
        {
          # P(X < a)
          text = paste0("P(X ", low_less, " a)")
        }
        else if (input$tail == "upper")
        {
          # P(X > a)
          text = paste0("P(X ", low_greater, " a)")
        }
        else if (input$tail == "middle")
        {
          # P(a < X < b)
          text = paste0("P(a ", low_less, " X ", up_less, " b)")
        }
        else if (input$tail == "both")
        {
          # P(X < a or X > b)
          text = paste0("P(X ", low_less, " a or X ", up_greater, " b)")
        }
        else if (input$tail == "equal")
        {
          # P(X = a)
          text = paste0("P(X = a)")
        }
      }

      return(text)
    })

  output$region = renderText(
    {
      get_region_text()
    })


  #############################
  # Normal distribution stuff #
  ############################

  output$mean = renderUI(
    {
      if (input$dist == "rnorm")
      {
        numericInput("mu",
                     "Mean",
                     value = 0)
      }
    })

  output$sd = renderUI(
    {
      #print("sd")
      if (input$dist == "rnorm")
      {
        numericInput("sd",
                     "Standard deviation",
                     value = 1)
      }
    })

  output$df_1 = renderUI(
    {
      if (input$dist == "rt")
      {
        numericInput("df",
                     "Degrees of freedom",
                     value = 10,
                     step=1,
                     min=1)
      }
      else if (input$dist == "rf")
      {
        numericInput("df_1",
                     "Numerator degrees of freedom",
                     value = 2,
                     step=1,
                     min=1)
      }
    })

  output$df_2 = renderUI(
    {
      if (input$dist == "rf")
      {
        numericInput("df_2",
                     "Denominator degrees of freedom",
                     value = 10,
                     step=1,
                     min=1)
      }
    })

  output$a = renderUI(
    {
      value = 1
      min = 0
      max = 1
      step = 1

      if (input$dist == "rnorm")
      {

        if (is.null(input$mu) | is.null(input$sd)){
          shiny:::flushReact()
          return()
        }

        mu = input$mu
        sd = input$sd
        if (is.null(mu)) mu = 0
        if (is.null(sd)) sd = 1

        value = mu - 1.96 * sd
        min   = mu - 4 * sd
        max   = mu + 4 * sd
        step  = 0.01
        if (mu == 0 & sd == 1) {step = .01}
      }
      else if (input$dist == "rt")
      {
        if (is.null(input$df)){
          shiny:::flushReact()
          return()
        }
        value = round(qt(0.025, df=as.numeric(input$df)), digits=2) 
        min   = -4
        max   = 4
        step  = 0.01
      }
      else if (input$dist == "rf")
      {
        if (is.null(input$df_1) | is.null(input$df_2)){
          shiny:::flushReact()
          return()
        }
        value = round(qf(.95,as.numeric(input$df_1),as.numeric(input$df_2)),digits=2)
        min   = 0
        max   = round(qf(.995,as.numeric(input$df_1),as.numeric(input$df_2))*1.05,digits=2)
        step  = 0.01
      }

      numericInput("a", 
                   label = "a",
                   value = value,
                   step=step,
                   min=min,
                   max=max)

    })

  output$b = renderUI(
    {
      if (is.null(input$tail))
      {
        shiny:::flushReact()
        return()
      }

      if (input$tail %in% c("middle","both"))
      {
        value = 1
        min = 0
        max = 1
        step = 1

        if (input$dist == "rnorm")
        {
          if (is.null(input$mu) | is.null(input$sd)){
            shiny:::flushReact()
            return()
          }

          mu = input$mu
          sd = input$sd
          if (is.null(mu)) mu = 0
          if (is.null(sd)) sd = 1

          value = mu + 1.96 * sd
          min   = mu - 4 * sd
          max   = mu + 4 * sd
          step  = 0.01
        }
        else if (input$dist == "rt")
        {
          value = round(qt(0.975, df=as.numeric(input$df)), digits=2)
          min   = -4
          max   = 4
          step  = 0.01
        }

        numericInput("b",
                     label = "b",
                     value = value,
                     step=step,
                     min=min,
                     max=max)
      }
    })  

  ############
  # Plotting #
  ############

  output$plot = renderPlot(
    { 
      if (is.null(input$tail) | is.null(input$a))
      {
        shiny:::flushReact()
        return()
      }

      L = NULL
      U = NULL

      error = FALSE

      if (input$tail == "lower" | input$tail == "equal")
      {
        L = input$a 
      }
      else if (input$tail == "upper")
      {
        U = input$a 
      }
      else if (input$tail %in% c("both","middle"))
      {
        if (is.null(input$b)){
          shiny:::flushReact()
          return()
        }

        L = input$a
        U = input$b

        if (L > U)
          error = TRUE
      }

      if (error)
      {
        plot(0,0,type='n',axes=FALSE,xlab="",ylab="",mar=c(1,1,1,1))
        text(0,0,"Error: Lower bound greater than upper bound.",col="red",cex=2)
      }
      else
      {
        if (input$dist == "rnorm" | input$dist == "rt") 
        {
          M = NULL
          if (input$tail == "middle")
          {
            M = c(L,U)
            L = NULL
            U = NULL
          }

          if(input$dist == "rnorm")
          {
            if(is.null(input$mu) | is.null(input$sd))
            {
              shiny:::flushReact()
              return()
            }

            normTail(m=input$mu, s=input$sd, L=L, U=U, M=M, axes=3, cex.axis=1.5)
            title(main="Normal Distribution")
          }
          else if (input$dist == "rt")
          {
            if(is.null(input$df))
            {
              shiny:::flushReact()
              return()
            }

            normTail(m=0, s=1, df=input$df, L=L, U=U, M=M, axes=3, cex.axis=1.5)
            title(main="t Distribution")
          }
        }
        else if (input$dist == "rf")
        {        
          if(is.null(input$df_1) | is.null(input$df_2))
          {
            shiny:::flushReact()
            return()
          }


          FTail(U=U,df_n=input$df_1, df_d=input$df_2)
          title(main="F Distribution")
        }

      }
    })

  ################
  # Calculations #
  ################

  output$area = renderText(
    {
      if (is.null(input$tail) | is.null(input$a))
      {
        shiny:::flushReact()
        return()
      }

      L = input$a
      U = NULL

      if (input$tail %in% c("both","middle")) 
      {
        if (is.null(input$b))
        {
          shiny:::flushReact()
          return()
        }

        U = input$b

        error = FALSE
        if (L>U) error = TRUE
        if (error){
          return()
        }
      }



      f = function() NULL

      if (input$dist == "rnorm")
      {
        if (is.null(input$mu) | is.null(input$sd))
        {
          shiny:::flushReact()
          return()
        }

        f = function(x) pnorm(x,input$mu,input$sd)
      }  
      else if (input$dist == "rt")
      {
        if (is.null(input$df))
        {
          shiny:::flushReact()
          return()
        }

        f = function(x) pt(x,input$df)
      }
      else if (input$dist == "rf"){
        if (is.null(input$df_1) | is.null(input$df_2))
        {
          shiny:::flushReact()
          return()
        }

        f = function(x) pf(x,input$df_1,input$df_2)
      }    


      val = NA
      if (input$tail == "lower")
        val = f(L)
      else if (input$tail == "upper")
        val = 1-f(L)
      else if (input$tail == "equal")
        val = f(L)
      else if (input$tail == "both")
        val = f(L) + (1-f(U))
      else if (input$tail == "middle")
        val = f(U) - f(L)

      text = paste("p = ",signif(val,3))


      text = sub("a",input$a,text)
      if (input$tail %in% c("both","middle")) 
        text = sub("b",input$b,text)

      text
    })
  } # close server 

)

bf_bic <- function(F, df1, df2, repeated=FALSE, report.as="BF01") {
  if (repeated==FALSE) {
    N = df1+df2+1
  } 
  else {
    N = df1+df2
  }

  bf = sqrt(N^df1*(1+F*df1/df2)^(-1*N))

  if (report.as=="BF01"){
    return(c(B01=bf))
  }
  else {
    return(c(B10=1/bf))
  }
}

bf_analytic <- function(F, df1, df2, alpha=0, repeated=FALSE, report.as="BF01") {
  if (repeated==FALSE) {

    C = suppressWarnings((gamma(df1/2+alpha+1)*gamma(df2/2))/(gamma((df1+df2)/2)*gamma(alpha+1)))
    bf = C*(df2/(df2+df1*F))^(alpha-df2/2+1)

  }
  else {

    C = suppressWarnings((gamma(df1/2+alpha+1)*gamma((df2-1)/2))/(gamma((df1+df2-1)/2)*gamma(alpha+1)))
    bf = C*(df2/(df2+df1*F))^(alpha-(df2-3)/2)
  }

  if (report.as == "BF01"){
    return(c(B01 = 1/bf))
  }
  else {
    return(c(B10 = bf))
  }
}

FTail <- function(U=NULL, df_n=100, df_d = 100, curveColor=1, border=1, col="#4F2D7F", xlim=NULL, ylim=NULL, xlab='', ylab='', detail=999){
    if(U <= 5){xlim <- c(0,5)}
    if(U > 5){xlim <- c(0,U+0.01*U)}
    temp <- diff(range(xlim))
    x    <- seq(xlim[1] - temp/4, xlim[2] + temp/4, length.out=detail)
    y    <- df(x, df_n, df_d)
    ylim <- range(c(0,y))
    plot(x, y, type='l', xlim=xlim, ylim=ylim, axes=FALSE, col=curveColor, xlab = "", ylab = "")
    these <- (x >= U)
    X <- c(x[these][1], x[these], rev(x[these])[1])
    Y <- c(0, y[these], 0)
    polygon(X, Y, border=border, col=col)
    abline(h=0)
    axis(1, at = c(0,U), label = c(NA,round(U,4)))
}

normTail <- function(m=0, s=1, L=NULL, U=NULL, M=NULL, df=1000, curveColor=1, border=1, col='#4F2D7F', xlim=NULL, ylim=NULL, xlab='', ylab='', digits=2, axes=1, detail=999, xLab=c('number', 'symbol'), cex.axis=1, xAxisIncr=1, ...){
    if(is.null(xlim)[1]){
      xlim <- m + c(-1,1)*3.5*s
    }
    temp <- diff(range(xlim))
    x    <- seq(xlim[1] - temp/4, xlim[2] + temp/4, length.out=detail)
    y    <- dt((x-m)/s, df)/s
    if(is.null(ylim)[1]){
      ylim <- range(c(0,y))
    }
    plot(x, y, type='l', xlim=xlim, ylim=ylim, xlab=xlab, ylab=ylab, axes=FALSE, col=curveColor, ...)
    if(!is.null(L[1])){
      these <- (x <= L)
      X <- c(x[these][1], x[these], rev(x[these])[1])
      Y <- c(0, y[these], 0)
      polygon(X, Y, border=border, col=col)
    }
    if(!is.null(U[1])){
      these <- (x >= U)
      X <- c(x[these][1], x[these], rev(x[these])[1])
      Y <- c(0, y[these], 0)
      polygon(X, Y, border=border, col=col)
    }
    if(all(!is.null(M[1:2]))){
      these <- (x >= M[1] & x <= M[2])
      X <- c(x[these][1], x[these], rev(x[these])[1])
      Y <- c(0, y[these], 0)
      polygon(X, Y, border=border, col=col)
    }

    if(axes == 1 || axes > 2){
      if(xLab[1]=='symbol'){
        xAt  <- m + (-3:3)*s
        xLab <- expression(mu-3*sigma, mu-2*sigma,
                           mu-sigma, mu,	mu+sigma,
                           mu+2*sigma, mu+3*sigma)
      } else if(xLab[1] != 'number'){
        stop('Argument "xLab" not recognized.\n')
      } else {
        temp <- seq(xAxisIncr, max(abs(xlim-m))/s, xAxisIncr)*s
        xAt <- m + c(-temp, 0, temp)
        xLab <- round(xAt, digits=digits)
      }
    }
    if(axes > 2){
      axis(1, at=xAt, labels=xLab, cex.axis=cex.axis)
      buildAxis(2, c(y,0), n=3, nMax=3, cex.axis=cex.axis)
    } else if(axes > 1){
      buildAxis(2, c(y,0), n=3, nMax=3, cex.axis=cex.axis)
    } else if(axes > 0){
      axis(1, at=xAt, labels=xLab, cex.axis=cex.axis)
    }

    abline(h=0)
}



# ---- Bayes factor helpers (base R replacements for BayesFactor/hypergeo) ----
# BayesFactor and hypergeo have no precompiled WebAssembly build for
# Shinylive/webR, so the functions below reimplement, in base R, exactly the
# calculations the app used to get from those two packages. Both were
# validated against the real packages (see shinylive_conversion_plan.md).

# Gauss hypergeometric function 2F1(a,b;c;z) via Euler's integral representation.
# Valid for Re(c) > Re(b) > 0 -- true for every (a,b,c,z) this app ever calls it
# with. Replaces hypergeo::f15.1.1() in the correlation Bayes factor formula.
hyp2f1 <- function(a, b, c, z) {
  integrand <- function(t) t^(b - 1) * (1 - t)^(c - b - 1) * (1 - z * t)^(-a)
  val <- integrate(integrand, lower = 0, upper = 1,
                    rel.tol = 1e-10, subdivisions = 500)$value
  val * gamma(c) / (gamma(b) * gamma(c - b))
}

# log(BF10) for a t-test from a t-statistic, replacing BayesFactor::ttest.tstat().
# JZS (Cauchy) prior on effect size (Rouder et al., 2009), integrated numerically.
# nullInterval restricts & renormalizes the effect-size prior to (A,B), which is
# how BayesFactor implements one-sided ("positive"/"negative" direction) tests.
ttestBF10log <- function(t, n1, n2 = NULL, nullInterval = c(-Inf, Inf),
                          rscale = sqrt(2) / 2) {
  if (is.null(n2)) {
    df   <- n1 - 1
    neff <- n1
  } else {
    df   <- n1 + n2 - 2
    neff <- (n1 * n2) / (n1 + n2)
  }

  A <- nullInterval[1]
  B <- nullInterval[2]

  integrand <- function(delta) {
    dt(t, df = df, ncp = delta * sqrt(neff)) *
      dcauchy(delta, location = 0, scale = rscale)
  }

  num <- integrate(integrand, lower = A, upper = B,
                    rel.tol = 1e-10, subdivisions = 500)$value
  prior_mass <- diff(pcauchy(c(A, B), location = 0, scale = rscale))

  m1 <- num / prior_mass      # restricted & renormalized alternative
  m0 <- dt(t, df = df)        # point-null (delta = 0)

  log(m1 / m0)
}


# ---- buildAxis() ----
# Vendored (verbatim) from the openintro R package (OpenIntroStat/openintro,
# R/buildAxis.R, author David Diez, GPL >= 3), because normTail() above calls
# it and openintro is not available as a WebAssembly binary for Shinylive/webR.
# It's pure base R already, so it's reproduced here rather than replaced.
buildAxis <- function(side, limits, n, nMin = 2, nMax = 10, extend = 2, eps = 10^-12, ...) {
  if (!all(is.finite(limits))) {
    stop("Must provide finite limits.\n")
  }
  limits <- range(limits)
  if (limits[1] == limits[2]) {
    stop('Range of "limits" is too small. Scale the data.\n')
  }

  L <- limits
  l <- L + c(-1, 1) * diff(L) * extend
  s <- sign(l)
  l10 <- round(log10(abs(l)))
  d <- diff(l)
  d10 <- round(log10(d))

  L1 <- L
  temp <- round(L1[1] / 10^(d10))
  L <- L1 - 10^(d10) * temp
  Lup <- temp * 10^(d10)
  l1 <- l
  l <- l1 - 10^(d10) * temp
  lup <- temp * 10^(d10)

  si <- list()
  si[[1]] <- seq(-6, 5, 0.01) / 10
  si[[2]] <- seq(-6, 5, 0.015) / 10
  si[[3]] <- seq(-6, 5, 0.02) / 10
  si[[4]] <- seq(-6, 5, 0.025) / 10
  si[[5]] <- seq(-6, 5, 0.03) / 10

  si[[6]] <- seq(-6, 5, 0.04) / 10
  si[[7]] <- seq(-6, 5, 0.05) / 10
  si[[8]] <- seq(-6, 5, 0.06) / 10
  si[[9]] <- seq(-7, 5, 0.07) / 10
  si[[10]] <- seq(-6, 5, 0.08) / 10

  AES <- c(
    8, 0, 7, 5, 3,
    4, 7, 2, 1, 2
  )
  for (i in 0:2) {
    for (j in 1:10) {
      temp <- round(10000 * si[[j]] * 10^i) / 10000
      si[[i * 10 + j]] <- temp
      AES[i * 10 + j] <- AES[j]
    }
  }

  if (0 >= L[1] && 0 <= L[2]) {
    start <- 0
  } else {
    start <- -10^max(round(log10(abs(L)) + 0.5))
    go <- rep(TRUE, 2)
    temp <- 10^max(round(log10(abs(L)) - 0.5))
    while (all(go)) {
      go <- FALSE
      if (start < L[1]) {
        start <- start + temp
        go <- TRUE
      }
    }
  }

  br <- list()
  se <- list()
  ss <- list()
  le <- c()
  for (i in 1:length(si)) {
    br[[i]] <- si[[i]] * 10^d10
    se[[i]] <- start + br[[i]]
    these <- (se[[i]] <= l[2] + eps) &
      (se[[i]] >= l[1] - eps)
    ss[[i]] <- se[[i]][these]
    these <- (se[[i]] <= L[2] + eps) &
      (se[[i]] >= L[1] - eps)
    le[i] <- sum(these)
    ss[[i]] <- ss[[i]] + Lup
  }
  L <- L1
  l <- l1

  these <- which(le >= nMin & le <= nMax)
  aes <- c()
  for (i in these) {
    min((ss[[i]][ss[[i]] > L[1]] - L[1]) / d)
    min((L[1] - ss[[i]][ss[[i]] < L[1]]) / d)
    abs(n - le[[i]])
    temp <- ss[[i]][ss[[i]] > L[1]] - L[1]
    temp1 <- -log(max(c(0.01, min(temp / d))), 5)
    temp <- L[1] - ss[[i]][ss[[i]] < L[1]]
    temp2 <- -log(max(c(0.01, min(temp / d))), 5)
    temp3 <- -abs(le[i] - n)^2 / (n + 1)
    AES[i] <- AES[i] + temp1 + temp2 + temp3
  }
  select <- which.max(AES[these])[1]

  l <- ss[[these[select]]]

  temp <- -round(log10(eps))
  l <- (round(l * 10^temp)) * 10^(-temp)
  axis(side, at = l, ...)
  invisible(l)
}

#!/usr/bin/env python3
"""
Re-apply PsyStat's customizations to a shinylive::export()'d index.html.

A fresh `shinylive::export()` always regenerates a bare index.html with
<title>Shiny App</title>, no description/OG tags, and a blank white screen
during the (15-30s) webR startup. Run this once after every future export
to reapply both fixes:

  1. Title + Open Graph / Twitter Card meta tags (for clean link previews
     on LinkedIn/Twitter/Facebook -- otherwise the page has nothing for
     those sites to show).
  2. A "Loading PsyStat..." overlay with a spinner, shown until the app
     has actually rendered inside its iframe (detected by polling for the
     navbar Shiny's navbarPage() produces). Confirmed working against the
     live site on 2026-09-06: without this, the page is 100% blank/white
     for the entire webR boot time, which is a big part of why the load
     *feels* slower than it is.

This replaces the older add_social_meta.py -- use this one going forward.

Usage:
    python3 patch_shinylive_index.py /path/to/exported/psystat/index.html
"""
import sys

TITLE = "PsyStat"
DESCRIPTION = (
    "A free, browser-based calculator for probabilities and Bayes factors "
    "(t-tests, correlations, ANOVA) -- companion app to "
    "Psychological Statistics: The Basics."
)
URL = "https://tomfaulkenberry.github.io/psystat/"

HEAD_BLOCK = f"""    <title>{TITLE}</title>
    <meta name="description" content="{DESCRIPTION}" />

    <meta property="og:type" content="website" />
    <meta property="og:url" content="{URL}" />
    <meta property="og:title" content="{TITLE}" />
    <meta property="og:description" content="{DESCRIPTION}" />

    <meta name="twitter:card" content="summary" />
    <meta name="twitter:title" content="{TITLE}" />
    <meta name="twitter:description" content="{DESCRIPTION}" />

    <style>
      #psystat-loading {{
        position: fixed;
        inset: 0;
        z-index: 9999;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        gap: 1em;
        background: #ffffff;
        font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
        color: #4F2D7F;
        transition: opacity 0.3s ease;
      }}
      #psystat-loading .psystat-spinner {{
        width: 40px;
        height: 40px;
        border: 4px solid #e5ddf0;
        border-top-color: #4F2D7F;
        border-radius: 50%;
        animation: psystat-spin 0.8s linear infinite;
      }}
      #psystat-loading .psystat-subtext {{
        font-size: 0.85em;
        color: #777;
      }}
      @keyframes psystat-spin {{
        to {{ transform: rotate(360deg); }}
      }}
    </style>"""

BODY_BLOCK = """  <body>
    <div id="psystat-loading">
      <div class="psystat-spinner"></div>
      <div>Loading PsyStat&hellip;</div>
      <div class="psystat-subtext">(first load can take 15&ndash;30 seconds)</div>
    </div>
    <div style="height: 100vh; width: 100vw" id="root"></div>
    <script>
      (function () {
        var overlay = document.getElementById("psystat-loading");
        var attempts = 0;
        var maxAttempts = 200; // ~200 * 300ms = 60s safety cap
        var timer = setInterval(function () {
          attempts++;
          var iframe = document.querySelector("#root iframe");
          var ready = false;
          try {
            ready = !!(iframe && iframe.contentDocument &&
              iframe.contentDocument.querySelector(".navbar"));
          } catch (e) {
            ready = false;
          }
          if (ready || attempts >= maxAttempts) {
            clearInterval(timer);
            overlay.style.opacity = "0";
            setTimeout(function () { overlay.remove(); }, 300);
          }
        }, 300);
      })();
    </script>
  </body>"""


def main():
    if len(sys.argv) != 2:
        print(__doc__)
        sys.exit(1)

    path = sys.argv[1]
    with open(path) as f:
        content = f.read()

    if f"<title>{TITLE}</title>" in content and "psystat-loading" in content:
        print("Already fully patched -- nothing to do.")
        return

    old_title = "    <title>Shiny App</title>"
    if old_title in content:
        content = content.replace(old_title, HEAD_BLOCK)
    elif "psystat-loading" not in content:
        print(
            "Could not find the default '<title>Shiny App</title>' line, "
            "and the loading overlay isn't present either. The shinylive "
            "export format may have changed -- check index.html by hand."
        )
        sys.exit(1)

    old_body = """  <body>

    <div style="height: 100vh; width: 100vw" id="root"></div>

  </body>"""
    if old_body in content:
        content = content.replace(old_body, BODY_BLOCK)
    elif "psystat-loading" not in content:
        print(
            "Could not find the default <body> block to patch with the "
            "loading overlay. Check index.html by hand."
        )
        sys.exit(1)

    with open(path, "w") as f:
        f.write(content)
    print(f"Patched {path}")


if __name__ == "__main__":
    main()
